    orbit_os_write_stderr_selfhost((orbit_string)("  status                   Per-node health (alive/dead, draining flag)\n"));
    orbit_os_write_stderr_selfhost((orbit_string)("  drain <node>             Graceful stop of one node (finish in-flight, no restart)\n"));
    orbit_os_write_stderr_selfhost((orbit_string)("  restart --rolling        One node at a time, health-verified before the next\n"));
    orbit_os_write_stderr_selfhost((orbit_string)("  down                     Stop all nodes, remove state (no orphans left)\n"));
    orbit_os_write_stderr_selfhost((orbit_string)("  logs <node>              Print a node's log file\n"));
    orbit_os_write_stderr_selfhost((orbit_string)("  --quiet                  Only errors (status, logs and findings still print)\n"));
